css:
/* ========== Auros · 深渊终端 — 左侧固定边栏 · 深青水层仪器台 ========== */
body { font-size: 16px; line-height: 1.55; font-weight: 400; letter-spacing: 0; }
::selection { background: rgba(203, 255, 252, .22); color: #edfffe; }

/* 氛围层：生物荧光（青 + 磷粉），收敛到底色 */
.aurora i { filter: blur(120px); }
.aurora i:nth-child(1) { background: #00827c; opacity: .18; }
.aurora i:nth-child(2) { background: #fde9ff; opacity: .05; }
.aurora i:nth-child(3) { background: #00827c; opacity: .12; }

/* ================= 结构改造：header → 左侧固定边栏 ================= */
/* Liquid Deep 凹陷井通高竖栏：品牌在上、导航竖排、导入与主题选择沉底 */
header {
  position: fixed; left: 0; top: 0; bottom: 0; width: 236px; z-index: 50;
  flex-direction: column; align-items: stretch; gap: 0;
  padding: 36px 20px 24px; overflow-y: auto;
  background: #011d1c; border-bottom: 0; border-right: 1px solid rgba(255,255,255,.08);
  backdrop-filter: none; -webkit-backdrop-filter: none;
}
header.scrolled { background: #011d1c; border-bottom-color: transparent; }

/* 品牌区：仪器铭牌 */
.brand { margin-right: 0; padding: 0 10px 26px; border-bottom: 1px solid rgba(255,255,255,.08); margin-bottom: 24px; gap: 5px; }
.brand h1 { font-family: var(--font-display); font-weight: 500; font-size: 19px; letter-spacing: -.02em; }
.brand h1 em { color: #fde9ff; }
.brand .sub { font-family: "IBM Plex Mono", ui-monospace, "PingFang SC", monospace; font-size: 10px; letter-spacing: .15em; text-transform: uppercase; color: #bbc7c6; line-height: 1.6; }

/* 竖排导航：等宽大写 + 左侧读数刻度 */
nav { flex-direction: column; align-items: stretch; gap: 2px; background: transparent; border: 0; border-radius: 0; padding: 0; backdrop-filter: none; }
nav button {
  text-align: left; font: 500 11px/1 "IBM Plex Mono", ui-monospace, "PingFang SC", monospace;
  text-transform: uppercase; letter-spacing: .12em; color: #bbc7c6;
  padding: 12px 10px; border-radius: 0 6px 6px 0;
  border-bottom: 0; border-left: 2px solid transparent;
}
nav button:hover { color: #edfffe; background: rgba(0, 55, 52, .35); }
nav button.active { background: #003734; color: #ffffff; border-left-color: #fde9ff; border-bottom-color: transparent; }

/* 沉底操作区：导入 + 主题选择 */
#btn-import {
  margin-top: auto; width: 100%; border-radius: 6px; padding: 12px 14px;
  font: 500 11px/1 "IBM Plex Mono", ui-monospace, "PingFang SC", monospace;
  text-transform: uppercase; letter-spacing: .12em; color: #edfffe;
  background: transparent; border: 1px solid rgba(255,255,255,.18);
}
#btn-import:hover { border-color: #cbfffc; color: #ffffff; background: rgba(0, 55, 52, .4); }
#theme-switch {
  width: 100%; margin-top: 10px; border-radius: 6px; padding: 11px 12px;
  font: 500 11px/1 "IBM Plex Mono", ui-monospace, "PingFang SC", monospace;
  letter-spacing: .1em; text-transform: uppercase;
  background: #012624; border-color: rgba(255,255,255,.12); color: #bbc7c6;
}
#theme-switch:hover { border-color: #cbfffc; color: #edfffe; }

/* 主区让出边栏 */
main { max-width: none; margin: 0 0 0 236px; padding: 40px 56px 120px; }
.page { max-width: 1240px; }

/* ================= Hero：左上对齐仪表台头部，地球签名居右 ================= */
.hero {
  position: relative; grid-template-columns: 1fr 400px; gap: 48px;
  justify-items: start; text-align: left; align-items: center; align-content: center;
  min-height: 360px; padding: 44px 0 48px;
  border-bottom: 1px solid rgba(255,255,255,.08); margin-bottom: 48px;
}
/* earth 点阵地球：右侧仪器视窗，深井底 + 读数框线 */
.sig {
  display: block; order: 2; position: relative; z-index: 0;
  width: 400px; height: 400px; padding: 20px; pointer-events: none;
  background: #011d1c; border: 1px solid rgba(255,255,255,.08); border-radius: 16px;
}
.sig canvas { width: 100% !important; height: 100% !important; }
.hero > div:not(.sig):not(.nebula) { order: 1; position: relative; z-index: 1; }
.nebula { display: none; }

.hello {
  font-family: "IBM Plex Mono", ui-monospace, "PingFang SC", monospace;
  font-size: 11px; letter-spacing: .15em; color: #bbc7c6; margin-bottom: 22px;
}
.hello::before { content: ""; width: 8px; height: 8px; background: #fde9ff; flex: none; }
.hero-title {
  font-family: var(--font-display); font-weight: 500;
  font-size: clamp(34px, 3.6vw, 56px); line-height: 1.05; letter-spacing: -.04em;
  color: #ffffff; max-width: 22ch; margin-bottom: 22px;
}
.hero-title.long { font-size: clamp(26px, 2.6vw, 40px); line-height: 1.15; letter-spacing: -.03em; font-weight: 500; }
.hero-title .hl { background: none; -webkit-background-clip: initial; background-clip: initial; color: #fde9ff; -webkit-text-fill-color: #fde9ff; }
.hero-essence { font-size: 16px; line-height: 1.5; color: #bbc7c6; max-width: 56ch; margin-bottom: 22px; }
.hero-essence strong { color: #edfffe; font-weight: 500; }
.trend-row { justify-content: flex-start; margin: 0 0 28px; }
.trend { border-radius: 6px; background: rgba(0, 55, 52, .55); border-color: rgba(255,255,255,.1); backdrop-filter: none; font-family: "IBM Plex Mono", ui-monospace, "PingFang SC", monospace; font-size: 11px; letter-spacing: .08em; text-transform: uppercase; color: #bbc7c6; }
.trend b { color: #fde9ff; font-weight: 500; font-family: "IBM Plex Mono", ui-monospace, monospace; }

/* 按钮：Gradient Pill 主按钮 + Arrow Icon 幽灵按钮 */
.btn { display: inline-flex; align-items: center; border-radius: 6px; font: 500 13px/1 var(--font-body); text-transform: uppercase; letter-spacing: .1em; padding: 15px 26px; backdrop-filter: none; box-shadow: none; }
.btn:hover { transform: none; }
.btn.primary { background: linear-gradient(90deg, rgb(203,255,252) 0%, rgb(237,255,254) 26%, rgb(255,253,250) 48%, rgb(250,209,255) 89%); border: 0; color: #012624; border-radius: 999px; padding: 16px 32px; font-weight: 500; }
.btn.primary::after { content: "\2197"; margin-left: 10px; font-size: 14px; line-height: 1; transition: transform .2s; }
.btn.primary:hover { filter: brightness(1.06); box-shadow: none; }
.btn.primary:hover::after { transform: translate(2px, -2px); }
.btn.ghost { background: transparent; border: 1px solid rgba(255,255,255,.18); color: #edfffe; padding-right: 14px; }
.btn.ghost::after {
  content: "\2197"; display: inline-grid; place-items: center;
  width: 26px; height: 26px; margin-left: 12px; border-radius: 6px;
  background: rgba(3, 81, 75, .5); color: #ffffff; font-size: 13px; letter-spacing: 0;
  transition: transform .2s, background .2s;
}
.btn.ghost:hover { border-color: #cbfffc; background: transparent; }
.btn.ghost:hover::after { background: rgba(3, 81, 75, .9); transform: translate(1px, -1px); }
#status-bar .btn.ghost { padding: 4px 12px; }
#status-bar .btn.ghost::after { display: none; }

/* 统计带：4 列横排在仪表台头部下方，水层分层收边 */
.stat-row { gap: 20px; margin-bottom: 68px; padding-bottom: 68px; border-bottom: 1px solid rgba(255,255,255,.08); }

/* Statistic Counter：Surface Card + 动力学超大磷粉数字 */
.stat { background: #003734; border: 1px solid rgba(255,255,255,.08); border-radius: 16px; padding: 36px; box-shadow: none; backdrop-filter: none; transform: none !important; }
.stat:hover { border-color: rgba(203,255,252,.35); }
.stat .num { font-family: var(--font-num); font-weight: 500; font-size: clamp(48px, 3.6vw, 68px); line-height: 1.0; letter-spacing: -.046em; color: #fde9ff; transform: none; font-variant-numeric: tabular-nums; }
.stat .label { font-family: "IBM Plex Mono", ui-monospace, "PingFang SC", monospace; font-size: 12px; text-transform: uppercase; letter-spacing: .12em; color: #bbc7c6; margin-top: 18px; transform: none; }
.stat .spark { background: #fde9ff; opacity: .06; filter: blur(30px); }

/* 面板分层：主列 Surface（Kelp #003734 隆起），右栏 rail Recessed（Deep #011d1c 凹陷井） */
.dash-grid { gap: 20px; }
.panel { background: #003734; border: 1px solid rgba(255,255,255,.08); border-radius: 16px; padding: 36px; box-shadow: none; backdrop-filter: none; }
.panel:hover { border-color: rgba(203,255,252,.3); }
.rail { gap: 20px; }
.rail .panel { background: #011d1c; border-color: rgba(255,255,255,.06); padding: 40px 36px; }
.rail .panel:hover { border-color: rgba(203,255,252,.22); }
/* Uppercase Section Label：仪器读数式分区标签 */
.panel h3 { font-family: "IBM Plex Mono", ui-monospace, "PingFang SC", monospace; font-size: 11px; font-weight: 500; letter-spacing: .15em; text-transform: uppercase; color: #bbc7c6; margin-bottom: 22px; }
.rail .panel h3 { color: #8b9998; }
.panel h3::after { background: rgba(255,255,255,.1); }

.persona-md h1, .persona-md h2 { font-family: var(--font-display); font-weight: 500; font-size: 20px; letter-spacing: -.02em; color: #edfffe; line-height: 1.3; }
.persona-md p, .persona-md li { font-size: 15px; color: #bbc7c6; }
.persona-md strong { color: #edfffe; font-weight: 500; }
.persona-md blockquote { border-left: 2px solid #00827c; color: #bbc7c6; }

.tag-bar .name { font-size: 13px; color: #edfffe; }
.tag-bar .track { background: #011d1c; border-radius: 3px; height: 5px; }
.tag-bar .fill { background: linear-gradient(90deg, #00827c, #cbfffc); border-radius: 3px; }
.tag-bar .count { font-family: "IBM Plex Mono", ui-monospace, monospace; color: #bbc7c6; }
.mini-plan .mp-t { font-weight: 500; }
.mini-plan:hover .mp-t { color: #cbfffc; }
.mini-plan .mp-bar { background: #012624; }
.mini-plan .mp-fill { background: linear-gradient(90deg, #00827c, #cbfffc); }
.material-item { border-bottom-color: rgba(255,255,255,.07); }
.material-item .dot { background: #cbfffc; }

/* ================= 洞察页：仪器面板 ================= */
.insight-grid { gap: 20px; margin-top: 0; }
.fw-wall { gap: 16px; }
.fw-card {
  background: #003734; border: 1px solid rgba(255,255,255,.08); border-radius: 16px;
  padding: 24px; box-shadow: none; backdrop-filter: none;
}
.fw-card:hover { border-color: rgba(203,255,252,.35); transform: none; }
.fw-card .fw-name { font-weight: 500; font-size: 15px; letter-spacing: -.01em; color: #ffffff; }
.fw-card .fw-desc { color: #bbc7c6; }
.fw-card .fw-links a { font-family: "IBM Plex Mono", ui-monospace, monospace; color: #cbfffc; letter-spacing: .04em; }
.bp-row .bp-ends { font-size: 13px; color: #bbc7c6; }
.bp-row .bp-ends b { font-weight: 500; color: #edfffe; }
.bp-row .bp-ends .bp-val { font-family: "IBM Plex Mono", ui-monospace, monospace; color: #fde9ff; }
.bp-track { background: #011d1c; border-radius: 3px; }
.bp-fill { background: linear-gradient(90deg, #00827c, #cbfffc); border-radius: 3px; }
.bp-thumb { background: #fde9ff; box-shadow: 0 0 0 3px rgba(253,233,255,.12); }
.red-item { border-radius: 0 6px 6px 0; font-size: 13.5px; }
.gap-item { border-radius: 0 6px 6px 0; font-size: 13.5px; }
.corr-item { border-bottom-color: rgba(255,255,255,.1); font-size: 13.5px; color: #bbc7c6; }
.corr-item .c-no { font-family: "IBM Plex Mono", ui-monospace, monospace; color: #fde9ff; letter-spacing: .1em; }
.hm-cell { border-radius: 2px; background: rgba(253,233,255,.06); }
.hm-legend { font-family: "IBM Plex Mono", ui-monospace, "PingFang SC", monospace; font-size: 10px; letter-spacing: .1em; text-transform: uppercase; color: #8b9998; }
.insight-empty { color: #8b9998; font-size: 13.5px; }

/* 卡片页：kcard = Surface Card（Kelp 隆起面，36px 内边距，无阴影） */
.chip { border-radius: 6px; font: 500 11px/1 "IBM Plex Mono", ui-monospace, "PingFang SC", monospace; text-transform: uppercase; letter-spacing: .1em; padding: 9px 14px; backdrop-filter: none; }
.chip:hover { transform: none; border-color: #cbfffc; }
.chip.active { background: #fde9ff; border-color: #fde9ff; color: #012624; }
.search-box { border-radius: 6px; font-size: 13px; backdrop-filter: none; background: #011d1c; min-width: 280px; }
.search-box:focus { border-color: #cbfffc; }
.card-grid { gap: 20px; }
.kcard { background: #003734; border: 1px solid rgba(255,255,255,.08); border-radius: 16px; padding: 36px; box-shadow: none; backdrop-filter: none; transform: none !important; gap: 16px; position: relative; }
.kcard::after {
  content: "\2197"; position: absolute; top: 24px; right: 24px;
  width: 32px; height: 32px; border-radius: 6px; display: grid; place-items: center;
  background: rgba(3, 81, 75, .5); color: #ffffff; font-size: 14px;
  opacity: .85; transition: opacity .2s, background .2s;
}
.kcard:hover { border-color: rgba(203,255,252,.35); }
.kcard:hover::after { opacity: 1; background: rgba(3, 81, 75, .95); }
.kcard .ctitle { font-family: var(--font-display); font-weight: 500; font-size: 19px; line-height: 1.4; letter-spacing: -.02em; color: #ffffff; transform: none; padding-right: 36px; }
.kcard .cmeta { font-family: "IBM Plex Mono", ui-monospace, "PingFang SC", monospace; font-size: 11px; letter-spacing: .08em; text-transform: uppercase; color: #bbc7c6; transform: none; }
.kcard .csummary { font-size: 14px; color: #bbc7c6; transform: none; }
.kcard .ctags { transform: none; }
.mini-tag { border-radius: 6px; background: rgba(203,255,252,.08); color: #cbfffc; font-family: "IBM Plex Mono", ui-monospace, "PingFang SC", monospace; font-size: 10px; letter-spacing: .1em; text-transform: uppercase; padding: 5px 10px; }

/* 弹窗：Surface Card 气质 —— Kelp 面、16px 圆角、无阴影无边框 */
#modal-mask { background: rgba(1, 29, 28, .72); }
#modal { background: #003734; border: 0; border-radius: 16px; box-shadow: none; padding: 48px; }
#modal .close-x { color: #bbc7c6; }
#modal .close-x:hover { color: #ffffff; }
#modal h2 { font-family: var(--font-display); font-weight: 500; font-size: 32px; line-height: 1.1; letter-spacing: -.03em; color: #ffffff; }
#modal .mmeta { font-family: "IBM Plex Mono", ui-monospace, "PingFang SC", monospace; font-size: 11px; letter-spacing: .08em; text-transform: uppercase; color: #8b9998; }
#modal .mmeta a { color: #cbfffc; }
#modal .mbody { border-top-color: rgba(255,255,255,.1); }
.mbody h2 { font-family: "IBM Plex Mono", ui-monospace, "PingFang SC", monospace !important; font-size: 11px !important; letter-spacing: .15em !important; text-transform: uppercase; color: #fde9ff !important; }
.mbody li, .mbody p { font-size: 15px; color: #bbc7c6; }
#modal .edit-area { background: #011d1c; border-radius: 6px; border-color: rgba(255,255,255,.1); }
#modal .edit-area:focus { border-color: #cbfffc; }

/* 规划页：Surface Card */
.plan-list { gap: 20px; margin-top: 32px; }
.plan-card { background: #003734; border: 1px solid rgba(255,255,255,.08); border-radius: 16px; padding: 36px 40px; box-shadow: none; backdrop-filter: none; }
.plan-card:hover { border-color: rgba(203,255,252,.3); }
.plan-head .ptitle { font-family: var(--font-display); font-weight: 500; font-size: 20px; letter-spacing: -.02em; color: #ffffff; }
.status-badge { border-radius: 6px; font-family: "IBM Plex Mono", ui-monospace, "PingFang SC", monospace; font-size: 10px; letter-spacing: .12em; text-transform: uppercase; padding: 5px 11px; }
.status-badge.active { color: #fde9ff; border-color: rgba(253,233,255,.4); background: rgba(253,233,255,.07); }
.plan-meta { font-family: "IBM Plex Mono", ui-monospace, monospace; letter-spacing: .04em; }
.plan-goal { color: #bbc7c6; font-size: 14px; }
.progress-track { background: #011d1c; }
.progress-fill { background: linear-gradient(90deg, #00827c, #cbfffc); }
.progress-num { font-family: "IBM Plex Mono", ui-monospace, monospace; }
.task { border-bottom: 1px solid rgba(255,255,255,.08); font-size: 14.5px; }
.task input[type="checkbox"] { border-radius: 6px; border-color: #707777; }
.task input[type="checkbox"]:hover { border-color: #cbfffc; }
.task input[type="checkbox"]:checked { background: #cbfffc; border-color: #cbfffc; }
.task input[type="checkbox"]:checked::after { color: #012624; }

/* 图谱：Recessed 深井 */
#graph-box { background: #011d1c; border: 1px solid rgba(255,255,255,.06); border-radius: 16px; box-shadow: none; backdrop-filter: none; }

/* 时间线：Feature Row Card —— 行式透明卡 + 悬停箭头按钮 */
.tl::before { background: linear-gradient(#00827c, rgba(255,255,255,.08)); }
.tl-month::before { background: #fde9ff; box-shadow: 0 0 0 5px rgba(253,233,255,.1), 0 0 20px rgba(253,233,255,.5); }
.tl-month .mname { font-family: var(--font-num); font-weight: 500; font-size: 20px; letter-spacing: -.02em; color: #ffffff; }
.tl-item {
  background: transparent; border: 1px solid transparent; border-bottom: 1px solid rgba(255,255,255,.08);
  border-radius: 16px; padding: 22px 72px 22px 24px; margin-bottom: 6px; position: relative;
  backdrop-filter: none; transition: background .2s, border-color .2s;
}
.tl-item::after {
  content: "\2197"; position: absolute; right: 20px; top: 50%; transform: translateY(-50%) translate(-3px, 3px);
  width: 32px; height: 32px; border-radius: 6px; display: grid; place-items: center;
  background: rgba(3, 81, 75, .5); color: #ffffff; font-size: 14px;
  opacity: 0; transition: opacity .2s, transform .2s;
}
.tl-item:hover { background: rgba(0, 55, 52, .45); border-color: rgba(203,255,252,.25); transform: none; }
.tl-item:hover::after { opacity: 1; transform: translateY(-50%); }
.tl-item .t { font-weight: 500; color: #ffffff; font-size: 15px; letter-spacing: -.01em; }
.tl-item .d { color: #bbc7c6; font-family: "IBM Plex Mono", ui-monospace, "PingFang SC", monospace; font-size: 11px; letter-spacing: .06em; margin-top: 6px; }

/* 状态栏 / 通知：等宽仪表读数，让出边栏 */
#status-bar { left: 236px; right: 0; font-family: "IBM Plex Mono", ui-monospace, "PingFang SC", monospace; font-size: 11px; letter-spacing: .08em; text-transform: uppercase; color: #bbc7c6; background: #011d1c; border-top: 1px solid rgba(255,255,255,.08); padding: 10px 56px; backdrop-filter: none; -webkit-backdrop-filter: none; }
#status-bar .ok { color: #fde9ff; font-family: "IBM Plex Mono", ui-monospace, monospace; }
#toast { border-radius: 6px; border-color: #cbfffc; box-shadow: none; background: #011d1c; }

/* 拖拽遮罩：深井虚线投送口 */
#drop-mask { background: rgba(1, 29, 28, .85); backdrop-filter: blur(8px); }
#drop-mask .drop-inner { border: 1.5px dashed #cbfffc; border-radius: 16px; background: #011d1c; }
#drop-mask b { font-family: var(--font-display); font-weight: 500; letter-spacing: -.02em; color: #ffffff; }
#drop-mask span { font-family: "IBM Plex Mono", ui-monospace, "PingFang SC", monospace; font-size: 11px; letter-spacing: .06em; color: #bbc7c6; }

/* 落地页 */
#landing { margin-top: 15vh; gap: 24px; }
#landing .mark { border-radius: 16px; background: #003734; border: 1px solid rgba(255,255,255,.1); box-shadow: none; font-family: var(--font-display); font-weight: 500; color: #fde9ff; }
#landing h2 { font-family: var(--font-display); font-weight: 500; font-size: 40px; line-height: 1.05; letter-spacing: -.04em; color: #ffffff; }
#landing p { color: #bbc7c6; font-size: 16px; line-height: 1.5; }
.hint { font-family: "IBM Plex Mono", ui-monospace, "PingFang SC", monospace; font-size: 11px; letter-spacing: .1em; text-transform: uppercase; color: #bbc7c6; }

/* ================= 移动端兜底：边栏收回为顶部横条 ================= */
@media (max-width: 960px) {
  header {
    position: static; width: auto; flex-direction: row; flex-wrap: wrap; align-items: center;
    gap: 12px; padding: 16px 18px; overflow-y: visible;
    background: #011d1c; border-right: 0; border-bottom: 1px solid rgba(255,255,255,.08);
  }
  header.scrolled { background: #011d1c; }
  .brand { margin-right: auto; padding: 0; border-bottom: 0; margin-bottom: 0; }
  nav { flex-direction: row; flex-wrap: wrap; width: 100%; order: 3; gap: 4px; }
  nav button { padding: 9px 10px; border-left: 0; border-bottom: 2px solid transparent; border-radius: 0; }
  nav button:hover { background: transparent; }
  nav button.active { background: transparent; border-left-color: transparent; border-bottom-color: #fde9ff; }
  #btn-import { margin-top: 0; width: auto; padding: 9px 12px; }
  #theme-switch { width: auto; margin-top: 0; }
  main { margin-left: 0; padding: 20px 18px 80px; }
  .hero { grid-template-columns: 1fr; min-height: 0; padding: 40px 0 36px; gap: 28px; margin-bottom: 32px; }
  .sig { order: 2; width: min(74vw, 320px); height: min(74vw, 320px); padding: 14px; margin: 0 auto; }
  .stat-row { margin-bottom: 40px; padding-bottom: 40px; }
  .panel { padding: 26px 22px; }
  .rail .panel { padding: 30px 24px; }
  .kcard { padding: 26px 24px; }
  #status-bar { left: 0; padding: 10px 18px; }
}

/* ---- 与全局动效的适配：竖排导航不用底部下划线（active 已有左侧刻度+背景）；滚动进度条让出左边栏 ---- */
nav button::after { display: none; }
#scroll-progress { left: 236px; }
@media (max-width: 960px) {
  #scroll-progress { left: 0; }
}
